    public function toggle_status($id) {
        // Fetch current status
        $this->db->select('tbl_shift.id,user_shift_timings.is_active');
        $this->db->from('tbl_shift');
        $this->db->join('user_shift_timings', 'user_shift_timings.shift_id = tbl_shift.id');
        $this->db->where('user_shift_timings.id', $id);
        $query = $this->db->get();
        
        //echo '<pre>'; print_r($query->row()); echo '</pre>'; die;
        $current_status = $query->row()->is_active;

        // Toggle the status
        $new_status = ($current_status == 1) ? 0 : 1;

        // Update the status in the database
        $this->db->where('id', $id);
        $this->db->update('user_shift_timings', array('is_active' => $new_status));
    }

