    public function get_access_time($user_id) {
        $this->db->select('access_times.*');
        $this->db->from('users');
        $this->db->join('admins as sub_admin', 'users.sub_admin_id = sub_admin.id', 'left');
        $this->db->join('access_times', 'access_times.admin_id = COALESCE(sub_admin.id, (SELECT id FROM admins WHERE role = "super_admin" LIMIT 1))', 'left');
        $this->db->where('users.id', $user_id);
        $query = $this->db->get();
        return $query->row();
    }

